param(
    [string]$ProjectRoot = (Get-Location).Path,
    [switch]$SkipBuild
)

$ErrorActionPreference = "Stop"

function Write-Step {
    param([string]$Message)
    Write-Host ""
    Write-Host $Message -ForegroundColor Cyan
}

function Relative-Path {
    param(
        [string]$Root,
        [string]$FullName
    )

    return $FullName.Substring($Root.Length).TrimStart("\", "/")
}

$ProjectRoot = (Resolve-Path $ProjectRoot).Path
$ProjectParent = Split-Path $ProjectRoot -Parent
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $ProjectParent "stayknown-web-root-merge-backup-$Timestamp"
$BackupFilesRoot = Join-Path $BackupRoot "overwritten-root-files"
$BuildLog = Join-Path $ProjectRoot "stayknown-root-merge-build.log"

Write-Step "Validating the StayKnown website root..."

foreach ($required in @("package.json", "tsconfig.json", "app", "components", "lib")) {
    $requiredPath = Join-Path $ProjectRoot $required
    if (-not (Test-Path $requiredPath)) {
        throw "This does not look like the StayKnown website root. Missing: $required"
    }
}

$TsConfigText = Get-Content (Join-Path $ProjectRoot "tsconfig.json") -Raw
if ($TsConfigText -notmatch '"@/\*"\s*:\s*\[\s*"\.\/\*"\s*\]') {
    Write-Warning 'The script will not edit tsconfig.json, but the expected root alias "@/*": ["./*"] was not found.'
}

Write-Step "Preparing the verified root-only StayKnown payload..."

$PayloadBase64 = @'

'@

$TempRoot = Join-Path ([System.IO.Path]::GetTempPath()) "stayknown-root-merge-$Timestamp"
$TempZip = Join-Path $TempRoot "payload.zip"
$TempExtract = Join-Path $TempRoot "payload"

New-Item -ItemType Directory -Path $TempExtract -Force | Out-Null
[System.IO.File]::WriteAllBytes(
    $TempZip,
    [System.Convert]::FromBase64String($PayloadBase64)
)
Expand-Archive -Path $TempZip -DestinationPath $TempExtract -Force

$PayloadFiles = Get-ChildItem -Path $TempExtract -Recurse -File | Sort-Object FullName
if (-not $PayloadFiles) {
    throw "The embedded merge payload is empty."
}

Write-Step "Creating a recoverable backup outside the project..."
New-Item -ItemType Directory -Path $BackupFilesRoot -Force | Out-Null

$NewFiles = New-Object System.Collections.Generic.List[string]
$OverwrittenFiles = New-Object System.Collections.Generic.List[string]

foreach ($payloadFile in $PayloadFiles) {
    $relative = Relative-Path -Root $TempExtract -FullName $payloadFile.FullName
    $destination = Join-Path $ProjectRoot $relative

    if (Test-Path $destination) {
        $backupDestination = Join-Path $BackupFilesRoot $relative
        New-Item -ItemType Directory -Path (Split-Path $backupDestination -Parent) -Force | Out-Null
        Copy-Item -Path $destination -Destination $backupDestination -Force
        $OverwrittenFiles.Add($relative)
    } else {
        $NewFiles.Add($relative)
    }
}

$SourceDirectory = Join-Path $ProjectRoot "src"
if (Test-Path $SourceDirectory) {
    Write-Step "Moving the accidental src folder outside the active project..."
    Move-Item -Path $SourceDirectory -Destination (Join-Path $BackupRoot "src")
}

$NewFiles | Set-Content -Path (Join-Path $BackupRoot "new-files.txt")
$OverwrittenFiles | Set-Content -Path (Join-Path $BackupRoot "overwritten-files.txt")

Write-Step "Installing the new pages in root app, components, and lib folders..."

foreach ($payloadFile in $PayloadFiles) {
    $relative = Relative-Path -Root $TempExtract -FullName $payloadFile.FullName
    $destination = Join-Path $ProjectRoot $relative
    New-Item -ItemType Directory -Path (Split-Path $destination -Parent) -Force | Out-Null
    Copy-Item -Path $payloadFile.FullName -Destination $destination -Force
}

Write-Step "Confirming the final root architecture..."

$RequiredOutputs = @(
    "app\page.tsx",
    "app\layout.tsx",
    "app\features\page.tsx",
    "app\how-it-works\page.tsx",
    "app\plans\page.tsx",
    "app\trust-safety\page.tsx",
    "app\api\billing-region\route.ts",
    "components\StayKnownHomePage.tsx",
    "components\FeaturesExperience.tsx",
    "components\HowItWorksExperience.tsx",
    "components\PlansExperience.tsx",
    "components\TrustSafetyExperience.tsx",
    "lib\stayknown-billing-region.ts",
    "lib\stayknown-billing-types.ts",
    "lib\stayknown-home-content.ts"
)

foreach ($relative in $RequiredOutputs) {
    if (-not (Test-Path (Join-Path $ProjectRoot $relative))) {
        throw "Merge verification failed. Missing: $relative"
    }
}

if (Test-Path (Join-Path $ProjectRoot "src")) {
    throw "The src folder is still active after the merge."
}

Write-Step "Clearing old Next.js and TypeScript build caches..."

Remove-Item -Recurse -Force (Join-Path $ProjectRoot ".next") -ErrorAction SilentlyContinue
Remove-Item -Force (Join-Path $ProjectRoot "tsconfig.tsbuildinfo") -ErrorAction SilentlyContinue

if (-not $SkipBuild) {
    Write-Step "Running the clean production build..."

    Push-Location $ProjectRoot
    try {
        & npm.cmd run build 2>&1 | Tee-Object -FilePath $BuildLog
        $BuildExitCode = $LASTEXITCODE
    } finally {
        Pop-Location
    }

    if ($BuildExitCode -ne 0) {
        Write-Host ""
        Write-Host "The root merge completed, but the build reported another error." -ForegroundColor Yellow
        Write-Host "Build log: $BuildLog" -ForegroundColor Yellow
        Write-Host "Backup: $BackupRoot" -ForegroundColor Yellow
        exit $BuildExitCode
    }
}

Remove-Item -Recurse -Force $TempRoot -ErrorAction SilentlyContinue

Write-Host ""
Write-Host "StayKnown root merge completed successfully." -ForegroundColor Green
Write-Host "Project: $ProjectRoot" -ForegroundColor Green
Write-Host "Backup: $BackupRoot" -ForegroundColor Green
if ($SkipBuild) {
    Write-Host "Build skipped. Run npm run build from the project root." -ForegroundColor Yellow
} else {
    Write-Host "Production build passed." -ForegroundColor Green
}